import{_ as e,o as n,c as t,a4 as o}from"./chunks/framework.BRzJ4ijD.js";const d=JSON.parse('{"title":"第九部分 · 计算理论（Formal Languages / Automata / Complexity）","description":"","frontmatter":{},"headers":[],"relativePath":"theory/index.md","filePath":"theory/README.md","lastUpdated":1788475713000}'),i={name:"theory/index.md"};function l(s,a,r,p,u,h){return n(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="第九部分-·-计算理论-formal-languages-automata-complexity" tabindex="-1">第九部分 · 计算理论（Formal Languages / Automata / Complexity） <a class="header-anchor" href="#第九部分-·-计算理论-formal-languages-automata-complexity" aria-label="Permalink to &quot;第九部分 · 计算理论（Formal Languages / Automata / Complexity）&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p><strong>计算理论</strong>回答两个根本问题：<strong>(1) 什么是&quot;可计算&quot;？</strong>(2) <strong>什么是&quot;高效可计算&quot;？</strong> 前者把所有&quot;能算的事情&quot;用形式化机器（自动机、图灵机）框死，并给出绝对不可逾越的边界（停机问题、Rice 定理）；后者把&quot;高效&quot;形式化为复杂度类 P / NP / PSPACE，告诉你哪些问题注定无法在多项式时间内解。所有工程上的&quot;优化是 NP-hard&quot;、&quot;这条正则匹配不上&quot;、&quot;语言不可判定&quot;——都源自这里。它是把 DSA、编译原理、密码学（基于 NP 困难）连接起来的那一层。</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[正则匹配 /^(a|b)*ab$/ on &quot;aaaab&quot;]</span></span>
<span class="line"><span>  └─&gt; 正则 → ε-NFA → 子集构造 → DFA → 状态机驱动 (常数时间每字符)</span></span>
<span class="line"><span>       │       (字典树 / AC 自动机 / ReDoS 防护都建立在这里)</span></span>
<span class="line"><span>       └─&gt; 但是 (a^n b^n) 正则匹配不上 → 需要更高层级: PDA</span></span>
<span class="line"><span>             └─&gt; PDA ⇔ CFG ⇔ 上下文无关 → parser 用的 LR/LALR</span></span>
<span class="line"><span>                   └─&gt; 但 (a^n b^n c^n) PDA 也匹配不上 → 需要 TM</span></span>
<span class="line"><span>                         └─&gt; TM 能算所有&quot;可计算&quot;问题</span></span>
<span class="line"><span>                               └─&gt; 但是停机问题不可判定: 没有算法能判断任意程序是否会停</span></span>
<span class="line"><span>                                     └─&gt; Rice 定理: 任意非平凡语义性质都不可判定</span></span>
<span class="line"><span>                                           └─&gt; P vs NP: 多项式可验证 ≠ 多项式可解?</span></span>
<span class="line"><span>                                                 └─&gt; NPC 归约: 3-SAT → Clique → Vertex Cover...</span></span>
<span class="line"><span>                                                       └─&gt; 现代密码学 (RSA / 椭圆曲线) 假设 factoring/NP 不在 P</span></span></code></pre></div><h2 id="章节" tabindex="-1">章节 <a class="header-anchor" href="#章节" aria-label="Permalink to &quot;章节&quot;">​</a></h2><ul><li><a href="./">开篇：从正则到不可判定，计算的四级爬升</a> ← 当前</li><li><a href="./automata">1. 自动机：DFA → NFA → ε-NFA → 子集构造 → DFA 最小化</a></li><li><a href="./regular">2. 正则语言与泵引理</a></li><li><a href="./cfg-pda">3. 下推自动机（PDA）与上下文无关文法（CFG）</a></li><li><a href="./turing-machine">4. 图灵机：deterministic / non-deterministic / Church-Turing</a></li><li><a href="./undecidability">5. 不可判定性：停机问题、Rice 定理</a></li><li><a href="./complexity">6. Complexity classes：P / NP / NPC / co-NP / PSPACE</a></li><li><a href="./reductions">7. Polynomial-time reduction：3-SAT → Clique → Vertex Cover</a></li><li><a href="./approximation">8. Approximation algorithms、hardness of approximation</a></li><li><a href="./appendix">附录：常见判定问题分类速查表</a></li></ul><p>读完应能回答：</p><ol><li>为什么 <code>^(a|b)*ab$</code> 可以用 DFA 常数空间匹配，但 <code>^(a^n)(b^n)$</code> 必须用栈?</li><li>子集构造最坏情况会让 N 状态的 NFA 爆成 2ⁿ 状态的 DFA——这个下界是怎么构造的?</li><li>Pumping lemma 是必要非充分条件，那&quot;非正则&quot;的常规证法是什么? Myhill-Nerode 怎么给充要?</li><li>为什么 LR(1) 比 LL(1) 强但 parser 都更爱 LL? Chomsky 层级是怎么对应自动机层级的?</li><li>停机问题怎么用对角线法证明? Rice 定理为什么让&quot;程序是否 malware&quot;也变得不可判定?</li><li>P=NP 是七大千禧难题之一，为什么密码学家假设 NPA≠P? 如果 NPA 在 P，RSA 会立刻崩盘吗?</li><li>3-SAT 是 NPC 完备问题的&quot;Mona Lisa&quot;, 怎么从 3-SAT 归约到 Clique、Vertex Cover、TSP、Subset Sum?</li><li>什么问题在 PSPACE 但估计不在 NP? QBF / generalized geography / 围棋盘面判定</li><li>PTAS、APX-hard、Inapproximability ratio：为什么 set cover 估计比只能到 (ln n) 因子?</li></ol><h2 id="历史-1-1936-turing-与-church-各自独立" tabindex="-1">历史 1: 1936 Turing 与 Church 各自独立 <a class="header-anchor" href="#历史-1-1936-turing-与-church-各自独立" aria-label="Permalink to &quot;历史 1: 1936 Turing 与 Church 各自独立&quot;">​</a></h2><p>Turing 发表 &quot;On Computable Numbers&quot;, 用假想机器 (Turing Machine) 给出&quot;可计算&quot;的形式化; Church 同年用 λ-calculus 给出同样结论. 二者等价, 史称 <strong>Church-Turing Thesis</strong>——任何&quot;算法&quot;都能用 TM 表达。这是计算理论的奠基.</p><h2 id="历史-2-1956-kleene-1959-rabin-scott" tabindex="-1">历史 2: 1956 Kleene / 1959 Rabin-Scott <a class="header-anchor" href="#历史-2-1956-kleene-1959-rabin-scott" aria-label="Permalink to &quot;历史 2: 1956 Kleene / 1959 Rabin-Scott&quot;">​</a></h2><p>Kleene 给出正则语言定理; Rabin-Scott 1959 引入 DFA/NFA, 证明二者等价, 诞生子集构造法。1968 Thompson 把 NFA 编译成汇编, 这就是今天 grep / sed / RegEx 的源头（Thompson 构造法，第一部分 dsa/topics/string 里有提及）.</p><h2 id="历史-3-1936-godel-1931-不完备" tabindex="-1">历史 3: 1936 Gödel / 1931 不完备 <a class="header-anchor" href="#历史-3-1936-godel-1931-不完备" aria-label="Permalink to &quot;历史 3: 1936 Gödel / 1931 不完备&quot;">​</a></h2><p>Gödel 不完备定理先于 Turing 5 年: 任何强到包含 PA 的形式系统必有不可证真命题. 直接启发 Turing 的停机问题.</p><h2 id="历史-4-1971-cook-levin-1972-karp" tabindex="-1">历史 4: 1971 Cook-Levin / 1972 Karp <a class="header-anchor" href="#历史-4-1971-cook-levin-1972-karp" aria-label="Permalink to &quot;历史 4: 1971 Cook-Levin / 1972 Karp&quot;">​</a></h2><p>Cook-Levin 证明 SAT 是 NP-complete (第一个 NPC 问题); Karp 1972 列出 21 个经典 NPC 问题 (TSP / 3-SAT / Clique / Vertex Cover ...), 把&quot;对一个个具体问题找算法&quot;变成&quot;识别 NPC 后就停止找多项式算法&quot;——这是工程上最实用的一面.</p><h2 id="历史-5-1977-garey-johnson" tabindex="-1">历史 5: 1977 Garey &amp; Johnson <a class="header-anchor" href="#历史-5-1977-garey-johnson" aria-label="Permalink to &quot;历史 5: 1977 Garey &amp; Johnson&quot;">​</a></h2><p>&quot;Computers and Intractability: A Guide to the Theory of NP-Completeness&quot; 出版, 成为 NPC 问题的&quot;红宝书&quot;, 至今仍是工程师面对新问题的第一查询对象.</p><hr><p>下一节 → <a href="./automata">自动机：DFA → NFA</a></p>`,21)])])}const m=e(i,[["render",l]]);export{d as __pageData,m as default};
